drop policy if exists intelligence_runs_coach_read on public.intelligence_runs;
drop policy if exists intelligence_runs_coach_write on public.intelligence_runs;
create policy intelligence_runs_coach_read on public.intelligence_runs for select to authenticated using ((select public.iberfit_role()) = 'admin'::public.iberfit_role or public.is_assigned_coach(client_id));
create policy intelligence_runs_coach_insert on public.intelligence_runs for insert to authenticated with check ((select public.iberfit_role()) = 'admin'::public.iberfit_role or public.is_assigned_coach(client_id));
create policy intelligence_runs_coach_update on public.intelligence_runs for update to authenticated using ((select public.iberfit_role()) = 'admin'::public.iberfit_role or public.is_assigned_coach(client_id)) with check ((select public.iberfit_role()) = 'admin'::public.iberfit_role or public.is_assigned_coach(client_id));
create policy intelligence_runs_coach_delete on public.intelligence_runs for delete to authenticated using ((select public.iberfit_role()) = 'admin'::public.iberfit_role or public.is_assigned_coach(client_id));
drop policy if exists plan_change_proposals_coach_read on public.plan_change_proposals;
drop policy if exists plan_change_proposals_coach_write on public.plan_change_proposals;
